//! Request routing and the HTTP semantics of the key-value API.

use bytes::Bytes;
use http_body_util::Full;
use hyper::header::{ALLOW, CONTENT_TYPE, HeaderValue};
use hyper::{Method, Response, StatusCode};

use crate::store::Store;

/// Largest accepted value (and request body), in bytes.
pub const MAX_VALUE_SIZE: usize = 1024 * 1024;

const MAX_KEY_LEN: usize = 64;
const KV_PREFIX: &str = "/kv/";

pub type Body = Full<Bytes>;

/// Returns `true` if `key` matches `[A-Za-z0-9_-]{1,64}`.
pub fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Builds a response with the given status, body and optional content type.
pub fn response(
    status: StatusCode,
    body: Bytes,
    content_type: Option<&'static str>,
) -> Response<Body> {
    let mut res = Response::new(Full::new(body));
    *res.status_mut() = status;
    if let Some(ct) = content_type {
        res.headers_mut()
            .insert(CONTENT_TYPE, HeaderValue::from_static(ct));
    }
    res
}

pub fn empty(status: StatusCode) -> Response<Body> {
    response(status, Bytes::new(), None)
}

fn method_not_allowed(allow: &'static str) -> Response<Body> {
    let mut res = empty(StatusCode::METHOD_NOT_ALLOWED);
    res.headers_mut()
        .insert(ALLOW, HeaderValue::from_static(allow));
    res
}

/// Dispatches a fully-read request against the store.
pub fn handle(store: &Store, method: &Method, path: &str, body: Bytes) -> Response<Body> {
    match path {
        "/health" => match *method {
            Method::GET => response(
                StatusCode::OK,
                Bytes::from_static(b"ok"),
                Some("text/plain"),
            ),
            _ => method_not_allowed("GET"),
        },
        "/kv" => match *method {
            Method::GET => {
                let json =
                    serde_json::to_vec(&store.keys()).expect("a list of strings always serializes");
                response(StatusCode::OK, json.into(), Some("application/json"))
            }
            _ => method_not_allowed("GET"),
        },
        _ => match path.strip_prefix(KV_PREFIX) {
            Some(key) if is_valid_key(key) => handle_key(store, method, key, body),
            Some(_) => empty(StatusCode::BAD_REQUEST),
            None => empty(StatusCode::NOT_FOUND),
        },
    }
}

fn handle_key(store: &Store, method: &Method, key: &str, body: Bytes) -> Response<Body> {
    match *method {
        Method::GET => match store.get(key) {
            Some(value) => response(StatusCode::OK, value, Some("application/octet-stream")),
            None => empty(StatusCode::NOT_FOUND),
        },
        Method::PUT => {
            let status = if store.put(key, body) {
                StatusCode::CREATED
            } else {
                StatusCode::OK
            };
            empty(status)
        }
        Method::DELETE => {
            let status = if store.delete(key) {
                StatusCode::NO_CONTENT
            } else {
                StatusCode::NOT_FOUND
            };
            empty(status)
        }
        _ => method_not_allowed("GET, PUT, DELETE"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use http_body_util::BodyExt;

    fn call(store: &Store, method: Method, path: &str, body: &'static [u8]) -> (StatusCode, Bytes) {
        let res = handle(store, &method, path, Bytes::from_static(body));
        let status = res.status();
        let body = collect_body(res.into_body());
        (status, body)
    }

    fn collect_body(body: Body) -> Bytes {
        tokio::runtime::Builder::new_current_thread()
            .build()
            .unwrap()
            .block_on(body.collect())
            .unwrap()
            .to_bytes()
    }

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("é"));
    }

    #[test]
    fn routes() {
        let s = Store::new();
        assert_eq!(
            call(&s, Method::GET, "/health", b""),
            (StatusCode::OK, Bytes::from_static(b"ok"))
        );
        assert_eq!(
            call(&s, Method::POST, "/health", b"").0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(call(&s, Method::GET, "/nope", b"").0, StatusCode::NOT_FOUND);
        assert_eq!(
            call(&s, Method::GET, "/kv/", b"").0,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(
            call(&s, Method::GET, "/kv/a/b", b"").0,
            StatusCode::BAD_REQUEST
        );
        assert_eq!(call(&s, Method::PUT, "/kv/b", b"2").0, StatusCode::CREATED);
        assert_eq!(call(&s, Method::PUT, "/kv/a", b"1").0, StatusCode::CREATED);
        assert_eq!(call(&s, Method::PUT, "/kv/a", b"3").0, StatusCode::OK);
        assert_eq!(
            call(&s, Method::GET, "/kv/a", b""),
            (StatusCode::OK, Bytes::from_static(b"3"))
        );
        assert_eq!(
            call(&s, Method::PATCH, "/kv/a", b"").0,
            StatusCode::METHOD_NOT_ALLOWED
        );
        assert_eq!(
            call(&s, Method::GET, "/kv", b""),
            (StatusCode::OK, Bytes::from_static(br#"["a","b"]"#))
        );
        assert_eq!(
            call(&s, Method::DELETE, "/kv/a", b"").0,
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            call(&s, Method::DELETE, "/kv/a", b"").0,
            StatusCode::NOT_FOUND
        );
        assert_eq!(call(&s, Method::GET, "/kv/a", b"").0, StatusCode::NOT_FOUND);
    }
}

//! kvhttp: a minimal in-memory HTTP/1.1 key-value server (see SPEC.md).

mod app;
mod store;

use std::convert::Infallible;
use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use bytes::{Bytes, BytesMut};
use http_body_util::BodyExt;
use hyper::body::Incoming;
use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

use crate::app::{Body, MAX_VALUE_SIZE};
use crate::store::Store;

/// Why a request body could not be read.
enum BodyError {
    TooLarge,
    Malformed,
}

/// Reads the whole request body, refusing anything over [`MAX_VALUE_SIZE`].
///
/// An oversized body is still drained so the client reliably receives the
/// error response instead of a connection reset.
async fn read_body(mut body: Incoming) -> Result<Bytes, BodyError> {
    let mut buf = BytesMut::new();
    let mut too_large = false;
    while let Some(frame) = body.frame().await {
        let frame = frame.map_err(|_| BodyError::Malformed)?;
        let Ok(data) = frame.into_data() else {
            continue;
        };
        if too_large || buf.len() + data.len() > MAX_VALUE_SIZE {
            too_large = true;
            buf.clear();
        } else {
            buf.extend_from_slice(&data);
        }
    }
    if too_large {
        Err(BodyError::TooLarge)
    } else {
        Ok(buf.freeze())
    }
}

async fn serve(store: Arc<Store>, req: Request<Incoming>) -> Result<Response<Body>, Infallible> {
    let (parts, body) = req.into_parts();
    let res = match read_body(body).await {
        Ok(body) => app::handle(&store, &parts.method, parts.uri.path(), body),
        Err(BodyError::TooLarge) => app::empty(StatusCode::PAYLOAD_TOO_LARGE),
        Err(BodyError::Malformed) => app::empty(StatusCode::BAD_REQUEST),
    };
    Ok(res)
}

async fn run(port: u16) -> std::io::Result<()> {
    let listener = TcpListener::bind(SocketAddr::from((Ipv4Addr::LOCALHOST, port))).await?;
    let store = Arc::new(Store::new());
    loop {
        let (stream, _) = match listener.accept().await {
            Ok(conn) => conn,
            Err(err) => {
                // Transient failures such as running out of file descriptors
                // must not bring the server down.
                eprintln!("kvhttp: accept failed: {err}");
                continue;
            }
        };
        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let service = service_fn(move |req| serve(Arc::clone(&store), req));
            // Client disconnects and protocol errors only affect this connection.
            let _ = http1::Builder::new()
                .keep_alive(false)
                .serve_connection(TokioIo::new(stream), service)
                .await;
        });
    }
}

#[tokio::main]
async fn main() -> ExitCode {
    let mut args = std::env::args();
    let prog = args.next().unwrap_or_else(|| "kvhttp".into());
    let port = match (args.next().map(|p| p.parse::<u16>()), args.next()) {
        (Some(Ok(port)), None) => port,
        _ => {
            eprintln!("usage: {prog} <port>");
            return ExitCode::from(2);
        }
    };
    match run(port).await {
        Ok(()) => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("kvhttp: {err}");
            ExitCode::FAILURE
        }
    }
}

//! Thread-safe in-memory key-value store.

use std::collections::BTreeMap;
use std::sync::{Mutex, MutexGuard};

use bytes::Bytes;

/// In-memory key-value store shared by all connections.
///
/// Keys are kept ordered so listing them is a simple in-order walk.
#[derive(Debug, Default)]
pub struct Store {
    data: Mutex<BTreeMap<String, Bytes>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    /// Stores `value` under `key`, returning `true` if the key was new.
    pub fn put(&self, key: &str, value: Bytes) -> bool {
        self.lock().insert(key.to_owned(), value).is_none()
    }

    /// Returns the value stored under `key`, if any.
    pub fn get(&self, key: &str) -> Option<Bytes> {
        self.lock().get(key).cloned()
    }

    /// Removes `key`, returning `true` if it was present.
    pub fn delete(&self, key: &str) -> bool {
        self.lock().remove(key).is_some()
    }

    /// Returns every key in ascending order.
    pub fn keys(&self) -> Vec<String> {
        self.lock().keys().cloned().collect()
    }

    fn lock(&self) -> MutexGuard<'_, BTreeMap<String, Bytes>> {
        // No operation can leave the map in an inconsistent state, so a
        // poisoned lock is safe to keep using.
        self.data
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_delete() {
        let store = Store::new();
        assert!(store.put("a", Bytes::from_static(b"1")));
        assert!(!store.put("a", Bytes::from_static(b"2")));
        assert_eq!(store.get("a").as_deref(), Some(&b"2"[..]));
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }

    #[test]
    fn keys_are_sorted() {
        let store = Store::new();
        for key in ["b", "a", "c", "A", "_"] {
            store.put(key, Bytes::new());
        }
        assert_eq!(store.keys(), ["A", "_", "a", "b", "c"]);
    }
}
